SET standard_conforming_strings = ON;
DROP TABLE IF EXISTS "public"."routes" CASCADE;
BEGIN;
CREATE TABLE "public"."routes"();
ALTER TABLE "public"."routes" ADD COLUMN "ogc_fid" SERIAL CONSTRAINT "routes_pk" PRIMARY KEY;
SELECT AddGeometryColumn('public','routes','wkb_geometry',4326,'LINESTRING',2);
ALTER TABLE "public"."routes" ADD COLUMN "distance" NUMERIC(9,0);
CREATE INDEX "routes_wkb_geometry_geom_idx" ON "public"."routes" USING GIST ("wkb_geometry");
COMMIT;
